def loop_onset(t):
    lines=[x.strip() for x in t.split('\n') if x.strip()]
    seen=Counter(); pos=0
    for k,x in enumerate(lines):
        seen[x]+=1
        if seen[x]>=2: return k/len(lines), x[:70], len(lines)
